<?php $title='Produk';require '_head.php';if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: products.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO products(category_id,name,description,price,image,featured,active) VALUES(?,?,?,?,?,?,?)')->execute([(int)$_POST['category_id'],trim($_POST['name']),trim($_POST['description']),trim($_POST['price']),trim($_POST['image']),isset($_POST['featured'])?1:0,1]);header('Location: products.php');exit;}$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();?><h1>Produk</h1><div class="panel"><form method="post"><input name="name" placeholder="Nama produk" required><select name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><textarea name="description" placeholder="Keterangan (opsional)"></textarea><input name="price" placeholder="Harga (opsional)"><input name="image" placeholder="Path foto, contoh /uploads/products/nama.jpg"><label><input type="checkbox" name="featured"> Produk unggulan</label><br><button>Simpan</button></form></div><div class="panel"><table><?php foreach($rows as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['price'])?></td><td><a href="?delete=<?=$p['id']?>" onclick="return confirm('Hapus?')">Hapus</a></td></tr><?php endforeach;?></table></div><?php require '_foot.php';?>